#requires -Version 5.1
<#
WinBoost 0.9 - paquete PowerShell independiente.
Sin parametros: despliega los componentes y abre la interfaz.
-Mode Apply -Profile Gaming: ejecucion automatica.
-Mode Extract: extrae el codigo fuente sin iniciar la aplicacion.
El ZIP integrado contiene exactamente el directorio src/v0.9 del repositorio.
#>
[CmdletBinding()]
param(
 [ValidateSet('GUI','Apply','Preview','Restore','Diagnose','Extract','ActionsPreview','ActionsApply','ActionsRestore')][string]$Mode='GUI',
 [ValidateSet('Rapido','Gaming','Mantenimiento')][string]$Profile='Rapido',
 [string]$PresetPath,
 [switch]$OpenReport
)
$ErrorActionPreference='Stop'
if($Mode -ne 'Extract' -and $env:OS -ne 'Windows_NT'){throw 'WinBoost requiere Windows 11 x64.'}
if($PresetPath){$PresetPath=(Resolve-Path -LiteralPath $PresetPath -ErrorAction Stop).ProviderPath}
if($PSBoundParameters.ContainsKey('Profile') -and $Mode -notin @('Apply','Preview')){throw 'Profile solo se admite en Apply o Preview.'}
if($PresetPath -and $Mode -notin @('Apply','Preview','ActionsPreview','ActionsApply')){throw 'PresetPath no se admite en este modo.'}
if($Mode -in @('ActionsPreview','ActionsApply') -and -not $PresetPath){throw 'Indica -PresetPath con un plan de acciones JSON.'}
$package=''
$bytes=[Convert]::FromBase64String($package)
$sha=[Security.Cryptography.SHA256]::Create()
try{$actual=([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}
if($actual -ne '96784f392592cf4fb3498e17e22117dadfa17b421c90311f7d0e96d416daa480'){throw 'El paquete integrado esta danado.'}
$folder=if($env:LOCALAPPDATA){$env:LOCALAPPDATA}else{[IO.Path]::GetTempPath()}
$target=Join-Path (Join-Path $folder 'WinBoost/Packages/v0.9') ([guid]::NewGuid().ToString('N'))
[void][IO.Directory]::CreateDirectory($target)
$zip=Join-Path $target 'package.zip'
[IO.File]::WriteAllBytes($zip,$bytes)
Add-Type -AssemblyName System.IO.Compression.FileSystem
$reader=[IO.Compression.ZipFile]::OpenRead($zip)
try{
 foreach($entry in $reader.Entries){
  if($entry.FullName -match '(^[/\\]|(^|[/\\])\.\.([/\\]|$)|:)' -or $entry.Length -gt 5MB){throw 'Ruta de paquete no valida.'}
 }
}finally{$reader.Dispose()}
[IO.Compression.ZipFile]::ExtractToDirectory($zip,$target)
Remove-Item -LiteralPath $zip
Write-Host ('WinBoost 0.9 / Archivos: '+$target) -ForegroundColor Cyan
if($Mode -eq 'Extract'){return $target}
$nativePS=Join-Path $env:SystemRoot 'System32/WindowsPowerShell/v1.0/powershell.exe'
if(-not [Environment]::Is64BitProcess){$nativePS=Join-Path $env:SystemRoot 'Sysnative/WindowsPowerShell/v1.0/powershell.exe'}
$entry=Join-Path $target 'WinBoost.ps1'
$command='& '+("'"+$entry.Replace("'","''")+"'")+' -Mode '+$Mode
if($Mode -in @('Apply','Preview')){
 if($PresetPath){$command+=' -PresetPath '+("'"+$PresetPath.Replace("'","''")+"'")}else{$command+=' -Profile '+$Profile}
}
if($Mode -in @('ActionsPreview','ActionsApply')){$command+=' -PresetPath '+("'"+$PresetPath.Replace("'","''")+"'")}
if($OpenReport){$command+=' -OpenReport'}
$command+='; exit $LASTEXITCODE'
$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($command))
$child=Start-Process -FilePath $nativePS -ArgumentList @('-NoProfile','-STA','-ExecutionPolicy','Bypass','-EncodedCommand',$encoded) -Wait -PassThru
if($child.ExitCode -notin @(0,2)){throw ('WinBoost finalizo con codigo '+$child.ExitCode+'. Consulta los registros locales.')}
if($child.ExitCode -eq 2){Write-Warning 'WinBoost termino con avisos. Consulta el informe.'}
